const fs = require('node:fs');
const V = (m) => { console.error('AUTHORING_TOOLING_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('AUTHORING_TOOLING_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const control = 'scripts/devgov/devgov.mjs';
  if (!fs.existsSync(control)) H('load-bearing controller control file is missing: ' + control);
  const required = [
    'scripts/tooling/devgov-authoring-preflight.mjs',
    'tests/unit/devgovAuthoringPreflight.test.ts',
    'docs/architecture/devgov/DEV-GOV-AUTHORING-PROMPTS.md',
  ];
  const missing = required.filter((p) => !fs.existsSync(p));
  if (missing.length > 0) V('non-authoritative authoring tooling is absent: ' + missing.join(', '));
  console.log('AUTHORING_TOOLING_OK: helper, focused test, and prompt template are present while controller control exists');
} catch (e) {
  H('unexpected: ' + (e && e.stack ? e.stack : e));
}

