const cp = require('node:child_process');
const V = (m) => { console.error('AUTHORING_TOOLING_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('AUTHORING_TOOLING_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const win = process.platform === 'win32';
  const command = win ? 'npx.cmd' : 'npx';
  const r = cp.spawnSync(command, [
    'vitest', 'run', '--config', 'vitest.config.ts', '--project', 'unit',
    'tests/unit/devgovAuthoringPreflight.test.ts'
  ], { stdio: 'inherit', shell: win, timeout: 180000 });
  if (r.error || r.status === null) H('focused test could not execute: ' + (r.error ? r.error.message : 'signal ' + r.signal));
  if (r.status !== 0) V('focused authoring-preflight tests failed with exit ' + r.status);
  console.log('AUTHORING_TOOLING_OK: focused unit tests passed');
} catch (e) {
  H('unexpected: ' + (e && e.stack ? e.stack : e));
}

const cp = require('node:child_process');
const V = (m) => { console.error('AUTHORING_TOOLING_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('AUTHORING_TOOLING_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const sha = cp.execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
  if (!/^[0-9a-f]{40}$/.test(sha)) H('could not resolve candidate HEAD');
  const r = cp.spawnSync(process.execPath, [
    'scripts/tooling/devgov-authoring-preflight.mjs',
    '--definition', 'governance/devgov/units/dev-gov-authoring-tooling-01-v1.json',
    '--candidate-sha', sha,
    '--worktree', process.cwd(),
  ], { encoding: 'utf8', timeout: 240000 });
  if (r.error || r.status === null) H('authoring preflight could not execute: ' + (r.error ? r.error.message : 'signal ' + r.signal));
  let report;
  try { report = JSON.parse(r.stdout || ''); } catch (e) { H('authoring preflight did not emit JSON: ' + String(r.stdout).slice(0, 500)); }
  if (r.status !== 0 || report.result !== 'PASS') V('authoring preflight failed: ' + String(r.stderr).slice(0, 500) + ' ' + JSON.stringify(report.errors || []));
  if (report.authoritative !== false) H('authoring helper must explicitly report authoritative=false');
  if (report.controller_preflight?.status !== 'PASS') V('real controller preflight was not reused successfully');
  if (report.hygiene?.prettier?.status !== 'PASS') V('changed-file Prettier did not PASS: ' + JSON.stringify(report.hygiene?.prettier));
  if (report.hygiene?.eslint?.status !== 'PASS') V('changed-file ESLint did not PASS: ' + JSON.stringify(report.hygiene?.eslint));
  if (!Array.isArray(report.static_checks?.candidateOnlyRedReferences) || report.static_checks.candidateOnlyRedReferences.length === 0) {
    V('candidate-only RED reference detector was not exercised by this unit');
  }
  console.log('AUTHORING_TOOLING_OK: controller preflight reused, changed-file hygiene passed, authoring warnings remained non-authoritative');
} catch (e) {
  H('unexpected: ' + (e && e.stack ? e.stack : e));
}
